static void mix(uint64_t u){digest=(digest^u)*UINT64_C(1099511628211);}
static size_t key(unsigned id,unsigned char *buf){
    static const size_t lens[]={319,320,321,1024};size_t len=lens[id%4];
    for(unsigned j=0;j<len;j++)buf[j]=(unsigned char)(seed+id*17+j*37);
    for(unsigned j=0;j<4;j++)buf[j]=(unsigned char)(id>>(24-8*j));
    buf[7]=0;buf[31]=255;return len;
