static unsigned identify(const unsigned char *buf,size_t len,double score){
    CHECK(len>=4);unsigned id=0;for(unsigned j=0;j<4;j++)id=(id<<8)|buf[j];
    CHECK(id<total && live[id]);unsigned char expected[1024];CHECK(len==key(id,expected));
    CHECK(!memcmp(buf,expected,len) && bits(score)==bits(scores[id]));results++;return id;
