    *bytes+=zmalloc_usable_size(p);uint64_t n=0;
    if(p->isleaf){n=p->count;CHECK(n);zbtScoreLeaf *leaf=(zbtScoreLeaf *)p;
        for(unsigned i=0;i<p->count;i++){unsigned char *record=zbtScoreLeafRecord(leaf,i);if(record[0]==ZBT_PACKED_EXTERNAL){void *external=zbtExternalPointer(record);CHECK(external);*bytes+=zmalloc_usable_size(external);}}}
