}
static void masks(zbtreeSet *tree){
    unsigned ids[16];
    CHECK(zbtreeScores(tree,NULL,0,NULL)==0);
    /* First16 entries cover every key/score representation, including empty. */
    for(unsigned count=0;count<=16;count++)for(unsigned mask=0;mask<(1U<<count);mask++){
        for(unsigned i=0;i<count;i++)ids[i]=(mask&(1U<<i))?i:N+i;
        batch(tree,ids,count);
    }
    for(unsigned id=0;id<32;id++)for(unsigned count=0;count<=16;count++){
        for(unsigned i=0;i<count;i++)ids[i]=id;
        batch(tree,ids,count);
    }
}
static int cmp(const void *ap,const void *bp){
    unsigned a=*(const unsigned*)ap,b=*(const unsigned*)bp;
    if(values[a]<values[b])return -1;if(values[a]>values[b])return 1;
    size_t na=sdslen(keys[a]),nb=sdslen(keys[b]);int c=memcmp(keys[a],keys[b],na<nb?na:nb);
    return c?c:(na>nb)-(na<nb);
}
static void verify(zbtreeSet *tree){
    unsigned sorted[N+EXTRA],n=0;
    for(unsigned i=0;i<N+EXTRA;i++){
        double score=0;CHECK(zbtreeScore(tree,keys[i],&score)==live[i]);
        if(live[i]){CHECK(bits(score)==bits(values[i]));sorted[n++]=i;}
        CHECK(zbtreeScoreRaw(tree,(unsigned char*)keys[i],sdslen(keys[i]),NULL)==live[i]);
        CHECK(zbtreeScoreRaw(tree,(unsigned char*)keys[i],sdslen(keys[i]),&score)==live[i]);
        if(live[i])CHECK(bits(score)==bits(values[i]));
    }
    CHECK(zbtreeLength(tree)==n);qsort(sorted,n,sizeof(*sorted),cmp);
    for(int reverse=0;reverse<2;reverse++){
        zbtreeIterator it;CHECK(zbtreeIteratorStart(tree,reverse,&it)==(n!=0));
        for(unsigned j=0;j<n;j++){
            unsigned id=sorted[reverse?n-j-1:j];const unsigned char *ele;size_t len;double score;
            CHECK(zbtreeIteratorNext(&it,reverse,&ele,&len,&score));
            CHECK(len==sdslen(keys[id]) && !memcmp(ele,keys[id],len));CHECK(bits(score)==bits(values[id]));
        }
        CHECK(!zbtreeIteratorNext(&it,reverse,NULL,NULL,NULL));
    }
    checks++;
}
static void exercise(void){
    uint8_t hs[16]={0};hs[0]=seed;dictSetHashFunctionSeed(hs);
    const size_t lens[]={4,7,8,16,319,320,321,1024};
    double specials[]={-0.0,0.0,-DBL_MAX,DBL_MAX,-DBL_MIN,DBL_MIN,-DBL_TRUE_MIN,DBL_TRUE_MIN,
        nextafter(1.0,0.0),1.0,nextafter(1.0,2.0),-1.0,0.5,-0.5,42.0,-42.0};
    memset(live,0,sizeof(live));
    for(unsigned i=0;i<N+EXTRA;i++){
        unsigned char buf[1024];size_t len=i?lens[i%8]:0;memset(buf,i%2?0xff:0,sizeof(buf));
        for(unsigned j=0;j<4;j++)buf[j]=(i>>(8*j))&255;
        keys[i]=sdsnewlen(buf,len);values[i]=specials[i%16];
    }
    zbtreeSet *tree=zbtreeCreate();stage=0;
    unsigned ids[16];for(unsigned i=0;i<16;i++)ids[i]=i;
    for(unsigned count=0;count<=16;count++)batch(tree,ids,count);verify(tree);
    stage=1;
    for(unsigned i=0;i<N;i++){
        sds tmp=sdsnewlen(keys[i],sdslen(keys[i]));zbtreeInsertPosition pos;double old;
        CHECK(!zbtreeFindForAdd(tree,tmp,&old,&pos));zbtreeInsertNew(tree,values[i],tmp,&pos);live[i]=1;
        memset(tmp,0xa5,sdslen(tmp));sdsfree(tmp);
    }
    CHECK(tree->member_rehash!=NULL);
    unsigned loops=0;
    while(tree->member_rehash){
        for(unsigned i=0;i<16;i++)ids[i]=(i%3==0)?N+i:(loops*127+i*421)%N;
        batch(tree,ids,16);CHECK(++loops<100000);
    }
    CHECK(loops>0);verify(tree);stage=2;masks(tree);verify(tree);
    stage=3;
    CHECK(zbtreeDelete(tree,keys[3]));live[3]=0;
    for(unsigned i=0;i<16;i++)if(live[i]){
        zbtreeInsertPosition pos;double old;CHECK(zbtreeFindForAdd(tree,keys[i],&old,&pos));
        values[i]=specials[(i+7)%16];zbtreeUpdateScore(tree,keys[i],values[i],&pos);
    }
    masks(tree);verify(tree);
    stage=4;zbtreeSet *copy=zbtreeDup(tree);zbtreeFree(tree);tree=copy;
    for(unsigned i=0;i<16;i++)ids[i]=i;for(unsigned count=0;count<=16;count++)batch(tree,ids,count);verify(tree);
    stage=5;CHECK(zbtreeDeleteRangeByRank(tree,0,ULONG_MAX)==N-1);memset(live,0,sizeof(live));
    for(unsigned count=0;count<=16;count++)batch(tree,ids,count);verify(tree);zbtreeFree(tree);
    for(unsigned i=0;i<N+EXTRA;i++)sdsfree(keys[i]);
    printf("seed=%u PASS batches=%lu slots=%lu checks=%lu active_batches=%lu\n",seed,batches,slots,checks,active_batches);fflush(stdout);
}
int main(void){seed=17;exercise();seed=101;exercise();CHECK(active_batches>0);printf("PASS seeds=2 batches=%lu slots=%lu checks=%lu active_batches=%lu\n",batches,slots,checks,active_batches);}

/* Standalone sorted-vector oracle: no Redis server or tree internals. */
#include "server.h"
#include "zset_btree.h"
#include <float.h>
#include <inttypes.h>
#include <math.h>
#include <string.h>

#define N 257
typedef struct { sds key; double score; int live; } entry;
static entry model[N];
static unsigned long checks;
static uint64_t rng;
static unsigned active_seed, active_fixture, active_step;
#define CHECK(x) do { if (!(x)) { \
    fprintf(stderr, "seed=%u fixture=%u step=%u line=%d: %s\n", \
            active_seed, active_fixture, active_step, __LINE__, #x); abort(); \
} } while (0)

static uint64_t random64(void) {
    uint64_t z = (rng += UINT64_C(0x9e3779b97f4a7c15));
    z = (z ^ (z >> 30)) * UINT64_C(0xbf58476d1ce4e5b9);
    z = (z ^ (z >> 27)) * UINT64_C(0x94d049bb133111eb);
    return z ^ (z >> 31);
}
static uint64_t bits(double value) {
    uint64_t result;
    memcpy(&result, &value, sizeof(result));
    return result;
}
static double score(void) {
    static const double edge[] = {0.0, -0.0, DBL_MIN, -DBL_MIN, DBL_MAX,
        -DBL_MAX, DBL_TRUE_MIN, -DBL_TRUE_MIN, 1.0, -1.0, 0.5, -0.5,
        9007199254740992.0, -9007199254740992.0};
    uint64_t r = random64();
    if (r & 1) return edge[(r >> 1) % (sizeof(edge) / sizeof(*edge))];
    /* All exponent patterns except 0x7ff: arbitrary finite bit patterns. */
    r = (r & ~UINT64_C(0x7ff0000000000000)) | (((r >> 12) % 2047) << 52);
    double result;
    memcpy(&result, &r, sizeof(result));
    CHECK(isfinite(result));
    return result;
}
static int keycmp(const unsigned char *a, size_t alen, const unsigned char *b, size_t blen) {
    int c = memcmp(a, b, alen < blen ? alen : blen);
    return c ? c : (alen > blen) - (alen < blen);
}
static int compare(const void *a, const void *b) {
    const entry *x = *(entry * const *)a, *y = *(entry * const *)b;
    if (x->score < y->score) return -1;
    if (x->score > y->score) return 1;
    return keycmp((unsigned char *)x->key, sdslen(x->key), (unsigned char *)y->key, sdslen(y->key));
}
static size_t sorted(entry **order) {
    size_t count = 0;
    for (unsigned i = 0; i < N; i++) if (model[i].live) order[count++] = &model[i];
    qsort(order, count, sizeof(*order), compare);
    return count;
}
static void member_matches(entry *e, const unsigned char *key, size_t len, double value) {
    CHECK(len == sdslen(e->key));
    CHECK(!memcmp(key, e->key, len));
    CHECK(bits(value) == bits(e->score));
}
typedef struct { unsigned char seen[N]; unsigned long calls; } scan_state;
static void scan_member(void *ctx, const unsigned char *key, size_t len, double value) {
    scan_state *state = ctx;
    for (unsigned i = 0; i < N; i++) {
        if (len == sdslen(model[i].key) && !memcmp(key, model[i].key, len)) {
            CHECK(model[i].live);
            member_matches(&model[i], key, len, value);
            state->seen[i] = 1;
            state->calls++;
            return;
        }
    }
    CHECK(0 && "scan returned unknown binary member");
}
static void verify(zbtreeSet *tree) {
    entry *order[N];
    size_t count = sorted(order);
    CHECK(zbtreeLength(tree) == count);
    for (unsigned i = 0; i < N; i++) {
        double value = 123.0;
        CHECK(zbtreeScore(tree, model[i].key, &value) == model[i].live);
        if (model[i].live) CHECK(bits(value) == bits(model[i].score));
        CHECK(zbtreeScoreRaw(tree, (unsigned char *)model[i].key, sdslen(model[i].key), &value) == model[i].live);
        if (model[i].live) CHECK(bits(value) == bits(model[i].score));
        else CHECK(zbtreeRank(tree, model[i].key, 0, NULL) == -1);
    }
    for (unsigned start = 0; start < N; start += ZBT_SCORE_BATCH_SIZE) {
        sds keys[ZBT_SCORE_BATCH_SIZE];
        double values[ZBT_SCORE_BATCH_SIZE];
        unsigned count_batch = N - start < ZBT_SCORE_BATCH_SIZE ? N - start : ZBT_SCORE_BATCH_SIZE;
        unsigned expected = 0;
        for (unsigned j = 0; j < count_batch; j++) {
            keys[j] = model[start+j].key;
            if (model[start+j].live) expected |= 1U << j;
        }
        CHECK(zbtreeScores(tree, keys, count_batch, values) == expected);
        for (unsigned j = 0; j < count_batch; j++)
            if (expected & (1U << j)) CHECK(bits(values[j]) == bits(model[start+j].score));
    }
    for (int reverse = 0; reverse <= 1; reverse++) {
        zbtreeIterator it;
        CHECK(zbtreeIteratorStart(tree, reverse, &it) == (count != 0));
        for (size_t i = 0; i < count; i++) {
            const unsigned char *key;
            size_t len;
            double value;
            entry *e = order[reverse ? count-i-1 : i];
            CHECK(zbtreeIteratorNext(&it, reverse, &key, &len, &value));
            member_matches(e, key, len, value);
            CHECK(zbtreeRank(tree, e->key, reverse, &value) == (long)i);
            CHECK(bits(value) == bits(e->score));
        }
        CHECK(!zbtreeIteratorNext(&it, reverse, NULL, NULL, NULL));
    }
    for (size_t i = 0; i < count; i++) {
        zbtreeIterator it;
        const unsigned char *key;
        size_t len;
        double value;
        CHECK(zbtreeIteratorSeekRank(tree, i, &it));
        CHECK(zbtreeIteratorNext(&it, 0, &key, &len, &value));
        member_matches(order[i], key, len, value);
    }
    zbtreeIterator end;
    CHECK(!zbtreeIteratorSeekRank(tree, count, &end));
    scan_state state = {{0}, 0};
    uint64_t cursor = 0;
    unsigned long steps = 0;
    unsigned long hint = checks % 3 == 0 ? 1 : checks % 3 == 1 ? 7 : 64;
    do {
        cursor = zbtreeScan(tree, cursor, hint, scan_member, &state);
        CHECK(++steps < 1000000);
    } while (cursor);
    for (unsigned i = 0; i < N; i++) CHECK(state.seen[i] == model[i].live);
    CHECK(state.calls >= count); /* duplicate callbacks are legal */
    checks++;
}
static void put(zbtreeSet *tree, unsigned id, double value) {
    double old;
    zbtreeInsertPosition pos;
    int found = zbtreeFindForAdd(tree, model[id].key, &old, &pos);
    CHECK(found == model[id].live);
    if (found) {
        CHECK(bits(old) == bits(model[id].score));
        zbtreeUpdateScore(tree, model[id].key, value, &pos);
    } else if (id & 1) {
        zbtreeInsertNew(tree, value, model[id].key, &pos);
    } else {
        zbtreeInsertNewRaw(tree, value, (unsigned char *)model[id].key, sdslen(model[id].key), &pos);
    }
    model[id].score = value;
    model[id].live = 1;
}
static void keys_create(unsigned collisions) {
    const size_t lengths[] = {8, 16, 319, 320, 321, 1024};
    for (unsigned i = 0; i < N; i++) {
        size_t len = collisions ? lengths[i % 5] : (i < 8 ? i : lengths[i % 6]);
        unsigned char buf[1024];
        for (size_t j = 0; j < len; j++) buf[j] = (unsigned char)(j * 37 + i);
        for (size_t j = 0; j < len && j < 4; j++) buf[j] = (unsigned char)(i >> (j * 8));
        if (collisions) {
            unsigned want = i % 3 == 0 ? 0 : i % 3 == 1 ? 1 : 255;
            uint32_t nonce;
            for (nonce = 0; nonce < 1000000; nonce++) {
                for (unsigned j = 0; j < 4; j++) buf[4+j] = (unsigned char)(nonce >> (j * 8));
                if (((uint32_t)dictGenHashFunction(buf, len) >> 24) == want) break;
            }
            CHECK(nonce < 1000000);
        }
        model[i] = (entry){sdsnewlen(buf, len), 0, 0};
        for (unsigned j = 0; j < i; j++)
            CHECK(keycmp((unsigned char *)model[j].key, sdslen(model[j].key), buf, len) != 0);
    }
}
static void exercise(unsigned seed, unsigned fixture) {
    active_seed = seed; active_fixture = fixture; active_step = 0;
    rng = seed;
    uint8_t hash_seed[16];
    for (unsigned i = 0; i < sizeof(hash_seed); i++) hash_seed[i] = (uint8_t)random64();
    dictSetHashFunctionSeed(hash_seed);
    keys_create(fixture);
    zbtreeSet *tree = zbtreeCreate();
    unsigned permutation[N];
    for (unsigned i = 0; i < N; i++) permutation[i] = i;
    for (unsigned i = N-1; i; i--) {
        unsigned j = random64() % (i+1), tmp = permutation[i];
        permutation[i] = permutation[j]; permutation[j] = tmp;
    }
    verify(tree);
    for (unsigned i = 0; i < N; i++) {
        active_step = i;
        /* Equal-score runs force member ordering and dense same-tag leaves. */
        put(tree, permutation[i], fixture ? (i & 1 ? -0.0 : 0.0) : score());
        unsigned count = i+1;
        if (count <= 9 || count % 32 <= 1 || count >= 255) verify(tree);
    }
    verify(tree);
    for (unsigned step = 0; step < 2048; step++) {
        active_step = N + step;
        unsigned id = random64() % N;
        switch (random64() % 8) {
        case 0: case 1: case 2: case 3:
            put(tree, id, score());
            break;
        case 4:
            CHECK(zbtreeDelete(tree, model[id].key) == model[id].live);
            model[id].live = 0;
            break;
        case 5: {
            entry *order[N]; size_t count = sorted(order);
            if (count) {
                int reverse = random64() & 1;
                zbtreeDeleteEdge(tree, reverse);
                order[reverse ? count-1 : 0]->live = 0;
            }
            break;
        }
        case 6: {
            entry *order[N]; size_t count = sorted(order);
            if (count) {
                size_t start = random64() % count, end = start + random64() % 5;
                size_t clipped = end < count ? end : count-1;
                CHECK(zbtreeDeleteRangeByRank(tree, start, end) == clipped-start+1);
                for (size_t i = start; i <= clipped; i++) order[i]->live = 0;
            }
            break;
        }
        case 7:
            zbtreeReserve(tree, N * 4);
            break;
        }
        if (step % 31 == 0) verify(tree);
        if (step % 257 == 0) {
            zbtreeSet *copy = zbtreeDup(tree);
            verify(copy);
            zbtreeFree(copy);
            verify(tree);
        }
    }
    verify(tree);
    for (unsigned i = 0; i < N; i++) {
        CHECK(zbtreeDelete(tree, model[i].key) == model[i].live);
        model[i].live = 0;
    }
    verify(tree);
    zbtreeFree(tree);
    for (unsigned i = 0; i < N; i++) sdsfree(model[i].key);
    printf("seed=%u fixture=%u PASS cumulative_verifications=%lu\n", seed, fixture, checks);
    fflush(stdout);
}
int main(void) {
    const unsigned seeds[] = {1, 2, 3, 101, 102, 103};
    for (unsigned s = 0; s < sizeof(seeds)/sizeof(*seeds); s++)
        for (unsigned fixture = 0; fixture < 2; fixture++) exercise(seeds[s], fixture);
    printf("PASS: 12 fixtures, 24576 mutation steps, %lu full oracle verifications\n", checks);
    return 0;
}

/* Read-only structural observations; every mutation uses the public API. */
#include "../src/zset_btree.c"
#include <inttypes.h>
#define MAX_KEYS 14337
static sds keys[MAX_KEYS];
static double values[MAX_KEYS];
static unsigned char live[MAX_KEYS],seen[MAX_KEYS];
static unsigned count_keys,seed,case_no,stage;
static unsigned long checks,scan_calls,rebuild_cases,incremental_cases,active_cases;
#define CHECK(x) do{if(!(x)){fprintf(stderr,"seed=%u case=%u stage=%u line=%d: %s\n",seed,case_no,stage,__LINE__,#x);abort();}}while(0)
static uint64_t bits(double x){uint64_t v;memcpy(&v,&x,8);return v;}
static int compare(const void *ap,const void *bp){
    unsigned a=*(const unsigned*)ap,b=*(const unsigned*)bp;
    if(values[a]<values[b])return -1;if(values[a]>values[b])return 1;
    size_t al=sdslen(keys[a]),bl=sdslen(keys[b]);int c=memcmp(keys[a],keys[b],al<bl?al:bl);
    return c?c:(al>bl)-(al<bl);
}
static size_t sorted(unsigned *order){size_t n=0;for(unsigned i=0;i<count_keys;i++)if(live[i])order[n++]=i;qsort(order,n,sizeof(*order),compare);return n;}
static unsigned identify(const unsigned char *key,size_t len,double value){
    CHECK(len>=4);unsigned id=0;for(unsigned j=0;j<4;j++)id|=(unsigned)key[j]<<(8*j);
    CHECK(id<count_keys && live[id] && len==sdslen(keys[id]));
    CHECK(!memcmp(key,keys[id],len) && bits(value)==bits(values[id]));return id;
}
static void visit(void *ctx,const unsigned char *key,size_t len,double value){UNUSED(ctx);seen[identify(key,len,value)]=1;scan_calls++;}
static void scan(zbtreeSet *tree){
    memset(seen,0,count_keys);uint64_t cursor=0;unsigned steps=0;
    do{cursor=zbtreeScan(tree,cursor,7,visit,NULL);CHECK(++steps<100000);}while(cursor);
    for(unsigned i=0;i<count_keys;i++)CHECK(seen[i]==live[i]);
}
static void verify(zbtreeSet *tree){
    unsigned *order=zmalloc(count_keys*sizeof(*order));size_t n=sorted(order);
    CHECK(zbtreeLength(tree)==n);
    for(unsigned i=0;i<count_keys;i++){
        double score;CHECK(zbtreeScore(tree,keys[i],&score)==live[i]);
        if(live[i])CHECK(bits(score)==bits(values[i]));
        CHECK(zbtreeScoreRaw(tree,(unsigned char*)keys[i],sdslen(keys[i]),&score)==live[i]);
        if(live[i])CHECK(bits(score)==bits(values[i]));
    }
    CHECK(zbtreeScores(tree,NULL,0,NULL)==0);
    for(unsigned batch=0;batch<=16;batch++){
        sds members[16];double scores[18];unsigned mask=0;
        for(unsigned j=0;j<18;j++)scores[j]=-12345.5;
        for(unsigned j=0;j<batch;j++){unsigned id=(j%3==0?0:(j*997+case_no)%count_keys);members[j]=keys[id];if(live[id])mask|=1U<<j;}
        CHECK(zbtreeScores(tree,members,batch,scores+1)==mask);
        CHECK(bits(scores[0])==bits(-12345.5));
        for(unsigned j=batch+1;j<18;j++)CHECK(bits(scores[j])==bits(-12345.5));
        for(unsigned j=0;j<batch;j++)if(mask&(1U<<j)){
            unsigned id=(j%3==0?0:(j*997+case_no)%count_keys);CHECK(bits(scores[j+1])==bits(values[id]));
        }
    }
    for(int reverse=0;reverse<2;reverse++){
        zbtreeIterator it;CHECK(zbtreeIteratorStart(tree,reverse,&it)==(n!=0));
        for(size_t i=0;i<n;i++){
            const unsigned char *key;size_t len;double value;unsigned id=order[reverse?n-1-i:i];
            CHECK(zbtreeIteratorNext(&it,reverse,&key,&len,&value));CHECK(identify(key,len,value)==id);
            if(i%97==0 || i+1==n){CHECK(zbtreeRank(tree,keys[id],reverse,&value)==(long)i);CHECK(bits(value)==bits(values[id]));}
        }
        CHECK(!zbtreeIteratorNext(&it,reverse,NULL,NULL,NULL));
    }
    for(size_t i=0;i<n;i+=97){zbtreeIterator it;const unsigned char *key;size_t len;double value;
        CHECK(zbtreeIteratorSeekRank(tree,i,&it));CHECK(zbtreeIteratorNext(&it,0,&key,&len,&value));CHECK(identify(key,len,value)==order[i]);}
    zbtreeIterator end;CHECK(!zbtreeIteratorSeekRank(tree,n,&end));scan(tree);zfree(order);checks++;
}
static void exercise(unsigned n,unsigned deleted,unsigned position){
    count_keys=n;case_no++;stage=0;memset(live,0,sizeof(live));
    zbtreeSet *tree=zbtreeCreate();
    for(unsigned i=0;i<n;i++){zbtreeInsertNew(tree,values[i],keys[i],NULL);live[i]=1;}
    int active=tree->member_rehash!=NULL;
    CHECK(active==(n==7169 || n==14337));if(active)active_cases++;
    zbtreeSet *copy=zbtreeDup(tree);verify(copy);zbtreeFree(copy);
    scan(tree);CHECK((tree->member_rehash!=NULL)==active);
    unsigned *order=zmalloc(n*sizeof(*order));CHECK(sorted(order)==n);
    unsigned start=position==0?0:position==1?(n-deleted)/2:n-deleted;
    uint32_t before_id=tree->next_score_leaf_id;
    int rebuild=deleted>1024 && deleted>=n/10;stage=1;
    CHECK(zbtreeDeleteRangeByRank(tree,start,start+deleted-1)==deleted);
    for(unsigned i=start;i<start+deleted;i++)live[order[i]]=0;
    unsigned leaves=0;
    for(zbtScoreLeaf *leaf=tree->score_first;leaf;leaf=leaf->next){if(rebuild)CHECK(leaf->id==leaves);leaves++;}
    if(rebuild){CHECK(!tree->member_rehash && tree->next_score_leaf_id==leaves);rebuild_cases++;}
    else{CHECK(tree->next_score_leaf_id==before_id && leaves<before_id);incremental_cases++;}
    verify(tree);stage=2;copy=zbtreeDup(tree);zbtreeFree(tree);tree=copy;verify(tree);
    for(unsigned i=start;i<start+deleted;i++){unsigned id=order[i];zbtreeInsertNew(tree,values[id],keys[id],NULL);live[id]=1;}
    stage=3;verify(tree);CHECK(zbtreeLength(tree)==n);
    CHECK(zbtreeDeleteRangeByRank(tree,0,ULONG_MAX)==n);memset(live,0,n);stage=4;verify(tree);
    zbtreeFree(tree);zfree(order);
    printf("seed=%u case=%u n=%u cut=%u position=%u active=%d rebuild=%d PASS checks=%lu\n",seed,case_no,n,deleted,position,active,rebuild,checks);fflush(stdout);
}
int main(void){
    const unsigned sizes[]={7169,10240,10260,14337};
    const unsigned cuts[][2]={{1024,1025},{1024,1025},{1025,1026},{1432,1433}};
    const size_t lengths[]={8,319,320,321,1024};
    for(unsigned pass=0;pass<2;pass++){
        seed=pass?111:11;uint8_t hash_seed[16];for(unsigned i=0;i<16;i++)hash_seed[i]=(uint8_t)(seed+i*37);dictSetHashFunctionSeed(hash_seed);
        for(unsigned i=0;i<MAX_KEYS;i++){
